const fs = require("fs");
const path = require("path");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
setTimeout(() => broken("timed out"), 80000).unref();
process.env.WRANGLER_SEND_METRICS = "false";
const proj = "/tmp/proj";
fs.mkdirSync(proj, { recursive: true });
fs.writeFileSync(path.join(proj, "wrangler.json"), JSON.stringify({ name: "mail", compatibility_date: "2025-03-17", send_email: [{ name: "SEND_EMAIL" }] }));
process.chdir(proj);
const marker = "ludion-email-body-" + Date.now();
function find(dir, depth) {
  let out = [];
  let entries;
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return out; }
  for (const e of entries) {
    const p = path.join(dir, e.name);
    if (e.isDirectory() && depth > 0) out = out.concat(find(p, depth - 1));
    else if (e.isFile() && p.endsWith(".txt") && p.includes("email-text")) {
      try { if (fs.readFileSync(p, "utf8") === marker) out.push(p); } catch {}
    }
  }
  return out;
}
(async () => {
  const { getPlatformProxy } = require("wrangler");
  const proxy = await getPlatformProxy({ configPath: path.join(proj, "wrangler.json"), persist: false });
  try {
    await proxy.env.SEND_EMAIL.send({ from: "sender@example.com", to: "recipient@example.com", subject: "Hi", text: marker });
  } catch (e) { broken("send failed: " + e.message); }
  const inProject = find(path.join(proj, ".wrangler", "tmp", "email"), 4);
  const inSystem = find("/tmp", 5).filter((p) => !p.startsWith(proj + path.sep));
  await proxy.dispose();
  if (inSystem.length === 0) broken("email text file not found in the system temp directory either");
  if (inProject.length === 0) symptom("sent email text was not written under .wrangler/tmp/email in the project root");
  console.log("OK: email text written to " + inProject[0]);
  process.exit(0);
})().catch((e) => broken(String((e && e.stack) || e)));

